export type XY = [number, number];
export type XYZ = [number, number, number];
export type XYZW = [number, number, number, number];

export type TypedArray =
  Int8Array |
  Uint8Array |
  Int16Array |
  Uint16Array |
  Int32Array |
  Uint32Array |
  Uint8ClampedArray |
  //Float16Array |
  Float32Array |
  Float64Array;

export type VectorLike = TypedArray | number[];

const { max, min } = Math;

export const π = Math.PI;
export const τ = 2*π;

export const clamp = (x: number, a: number, b: number) => max(a, min(b, x));

export const cub = (x: number) => x * x * x;
export const sqr = (x: number) => x * x;

export const lerp = (a: number, b: number, t: number) => a * (1 - t) + b * t;
export const clerp = (a: number, b: number, t: number) => {
  const d = (((b - a + π) / τ) % 1) * τ - π;
  return lerp(a, a + d, t);
};

export const seq = (n: number, start: number = 0, step: number = 1) => Array.from({length: n}).map((_, i) => start + i * step);
